-- ============================================================================
-- IMPORTACIÓN: Datos del CSV 045_DPTO_AUTOMATIZACION_ARTUROMORENO.csv
-- Registro de actividades/tiempos del empleado Arturo Moreno
-- ============================================================================

-- 1. Crear tabla si no existe
CREATE TABLE IF NOT EXISTS public.actividades_empleado (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    empleado_nombre TEXT NOT NULL DEFAULT 'ARTURO MORENO',
    numero_empleado TEXT,
    fecha DATE NOT NULL,
    actividad TEXT NOT NULL,
    descripcion TEXT,
    servicio TEXT,
    hora_inicio TIME,
    hora_fin TIME,
    tiempo_total INTERVAL,
    horas_extras NUMERIC(5,2) DEFAULT 0,
    creado_en TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Índice para búsquedas rápidas
CREATE INDEX IF NOT EXISTS idx_actividades_empleado_fecha ON public.actividades_empleado(fecha);
CREATE INDEX IF NOT EXISTS idx_actividades_empleado_nombre ON public.actividades_empleado(empleado_nombre);

-- 3. Insertar datos del CSV (diciembre 2024 - enero 2025)

-- 4. Verificar
SELECT COUNT(*) as total_actividades FROM public.actividades_empleado;
